<script setup lang="ts">
import {environments,paints,upholsteryColors,backgrounds,lightPresets,interiorDetails} from '~/data/finishes'
const s=useAtelier(),audio=useAudio(),{t}=useLocale(),ready=ref(false),progress=ref(0),error=ref(''),tab=ref('paint'),viewer=ref(0),cabinFinishes=ref(false)
const vehicleScene=ref<{playIntro:()=>void,stopIntro:()=>void}>(),introPlaying=ref(false)
function revealScene(){ready.value=true}
function startIntro(){vehicleScene.value?.playIntro()}
const requestedCar=useRoute().query.car;if(typeof requestedCar==='string')s.select(requestedCar)
const tabs=[{id:'paint',ru:'Кузов',en:'Paint'},{id:'interior',ru:'Салон',en:'Interior'},{id:'environment',ru:'Окружение',en:'Environment'},{id:'details',ru:'Детали',en:'Details'}]
const paintName=computed(()=>{const p=paints.find(p=>p.hex===s.paint.value);return p?t(p.ru,p.en):t('Индивидуальный цвет','Custom finish')})
const upholsteryName=computed(()=>{const p=upholsteryColors.find(p=>p.hex===s.upholstery.value);return p?t(p.ru,p.en):t('Графит','Graphite')})
const detail=computed(()=>interiorDetails.find(d=>d.id===s.detail.value))
watch(()=>s.interior.value,v=>{document.body.style.overflow=v?'hidden':'';cabinFinishes.value=false;if(v)tab.value='interior';else s.detail.value=''})
onBeforeUnmount(()=>{document.body.style.overflow='';s.interior.value=false;audio.stop()})
function action(fn:()=>void){fn();audio.click()}
async function focus(id:string){s.focus.value='';await nextTick();s.focus.value=id}
async function inspect(id:string){s.detail.value='';await nextTick();s.detail.value=id}
let revealTimer:ReturnType<typeof setTimeout>|undefined
function finishLoading(){clearTimeout(revealTimer);progress.value=100;}
watch(()=>s.car.value.id,()=>{clearTimeout(revealTimer);ready.value=false;progress.value=0})
onBeforeUnmount(()=>clearTimeout(revealTimer))
function retry(){clearTimeout(revealTimer);error.value='';ready.value=false;progress.value=0;viewer.value++}
</script>
<template><div class="experience" :class="{'in-cockpit':s.interior.value,'cabin-finishes':cabinFinishes,'intro-playing':introPlaying}"><AtelierHeader />
 <div class="scene-wrap"><ClientOnly><VehicleScene ref="vehicleScene" @intro="introPlaying=$event" :key="viewer" @ready="finishLoading" @progress="progress=$event; if($event<100)ready=false" @error="error=$event" /></ClientOnly><div class="scene-shade" /></div>
 <SceneLoading @complete="revealScene" @revealed="startIntro" :active="!ready" :progress="progress" :title="s.car.value.name" :vehicle="s.car.value.brand+' / '+t('ШОУРУМ','SHOWROOM')" :error="error" @retry="retry" />
 <button v-if="introPlaying" class="intro-skip" @click="vehicleScene?.stopIntro()">{{t('ПРОПУСТИТЬ ОСМОТР','SKIP INTRO')}} →</button>
 <main><section class="hero"><div class="hero-heading"><h1>{{s.car.value.name.toUpperCase()}}</h1></div>
 <div class="hero-bottom"><div class="hero-specs"><div><strong>{{s.car.value.power}}<small>{{t('Л.С.','CV')}}</small></strong><span>{{t('МОЩНОСТЬ','POWER')}}</span></div><div><strong>{{s.car.value.accel}}<small>{{t('С','S')}}</small></strong><span>{{t('0—100 КМ/Ч','0—100 KM/H')}}</span></div><div><strong>{{s.car.value.speed}}<small>{{t('КМ/Ч','KM/H')}}</small></strong><span>{{t('МАКС. СКОРОСТЬ','TOP SPEED')}}</span></div></div><a href="#showroom" class="accent-button">{{t('ОТКРЫТЬ КОНФИГУРАТОР','ENTER SHOWROOM')}} <span>↗</span></a></div><div class="hero-foot"><a href="#showroom">↓ <span>{{t('К ВЫБОРУ ОТДЕЛКИ','EXPLORE THE FINISHES')}}</span></a><span>{{t('ПЕРЕТАЩИТЕ — ПОВОРОТ','DRAG TO ROTATE')}} <b>↔</b> {{t('КОЛЕСО — МАСШТАБ','WHEEL TO ZOOM')}}</span></div></section>
 <section id="showroom" class="showroom"><div class="configurator"><div class="config-heading"><span>{{s.car.value.name.toUpperCase()}} / {{t('КОНФИГУРАТОР','CONFIGURATOR')}}</span><span>↗</span></div><div class="config-tabs" role="tablist"><button v-for="item in tabs" :id="'tab-'+item.id" role="tab" :aria-selected="tab===item.id" :aria-controls="'panel-'+item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{t(item.ru,item.en)}}</button></div><div class="config-content" role="tabpanel" :id="'panel-'+tab" :aria-labelledby="'tab-'+tab">
 <template v-if="tab==='paint'"><div class="swatches paint-swatches"><button v-for="p in paints" :aria-label="t(p.ru,p.en)" :title="t(p.ru,p.en)" :aria-pressed="s.paint.value===p.hex" :class="{selected:s.paint.value===p.hex}" :style="{'--swatch':p.hex}" @click="action(()=>s.paint.value=p.hex)" /></div><div class="selection-label"><span>{{paintName}}</span><small>{{t('МЕТАЛЛИК','METALLIC FINISH')}}</small></div></template>
 <template v-else-if="tab==='interior'"><small class="field-caption">{{t('ЦВЕТ ОБИВКИ','UPHOLSTERY FINISH')}}</small><div class="swatches"><button v-for="p in upholsteryColors" :aria-label="t('Обивка: '+p.ru,'Upholstery: '+p.en)" :title="t(p.ru,p.en)" :aria-pressed="s.upholstery.value===p.hex" :class="{selected:s.upholstery.value===p.hex}" :style="{'--swatch':p.hex}" @click="action(()=>s.upholstery.value=p.hex)" /></div><div class="selection-label"><span>{{upholsteryName}}</span><small>{{t('КОЖА','LEATHER')}}</small></div></template>
 <template v-else-if="tab==='environment'"><div v-if="s.car.value.shape===0" class="option-buttons"><button v-for="e in environments" :class="{active:s.environment.value===e.id}" :aria-pressed="s.environment.value===e.id" @click="action(()=>s.environment.value=e.id)">{{t(e.ru,e.en)}}</button></div><p v-if="s.car.value.shape===0&&s.environment.value==='italy'" class="field-caption">{{t('Небольшие здания · деревья · спокойный фон','Small buildings · trees · calm background')}}</p><small class="field-caption">{{t('ЦВЕТ ОКРУЖЕНИЯ','BACKGROUND COLOR')}}</small><div class="swatches background-swatches"><button v-for="p in backgrounds" :aria-label="t('Фон: '+p.ru,'Background: '+p.en)" :title="t(p.ru,p.en)" :aria-pressed="s.background.value===p.hex" :class="{selected:s.background.value===p.hex}" :style="{'--swatch':p.hex}" @click="action(()=>{s.environment.value='studio';s.background.value=p.hex})" /></div><small class="field-caption">{{t('СВЕТОВАЯ СХЕМА','LIGHTING')}}</small><div class="option-buttons"><button v-for="l in lightPresets" :class="{active:s.lighting.value===l.id}" :aria-pressed="s.lighting.value===l.id" @click="action(()=>s.lighting.value=l.id)">{{t(l.ru,l.en)}}</button></div></template>
 <template v-else><p>{{t('Крупный план настоящих деталей модели. Цвет тормозных дисков зафиксирован.','Close-ups of the model’s details. Brake rotor color is fixed.')}}</p><div class="option-buttons"><button @click="action(()=>{s.interior.value=false;focus('wheel')})">{{t('Колёса и тормоза','Wheels & brakes')}}</button><button @click="action(()=>{s.interior.value=false;focus('rear')})">{{t('Задняя оптика','Rear lights')}}</button></div></template>
 </div><div class="vehicle-actions">
 <button class="vehicle-action" :class="{active:s.doors.value}" :aria-pressed="s.doors.value" :aria-label="s.doors.value?t('Закрыть двери','Close doors'):t('Открыть двери','Open doors')" @click="action(()=>s.doors.value=!s.doors.value)"><ActionIcon kind="door"/><span>{{s.doors.value?t('Закрыть двери','Close doors'):t('Открыть двери','Open doors')}}</span></button>
 <button v-if="[0,8].includes(s.car.value.shape)" class="vehicle-action window-action" :aria-pressed="s.windowsDown.value" @click="s.windowsDown.value=!s.windowsDown.value"><span>▱</span><span>{{s.windowsDown.value?t('Поднять окна','Raise windows'):t('Опустить окна','Lower windows')}}</span><b>{{s.windowsDown.value?'↑':'↓'}}</b></button><button class="vehicle-action enter-action" @click="action(()=>s.interior.value=true)"><ActionIcon kind="seat"/><span>{{t('В салон','Enter cabin')}}</span><b>↗</b></button>
 <button class="vehicle-action lamp-action" :class="{active:s.headlights.value}" :aria-pressed="s.headlights.value" :aria-label="t('Передние фары','Headlights')" @click="s.headlights.value=!s.headlights.value"><ActionIcon kind="lamp"/><span>{{t('Передние','Front lights')}}</span><i/></button>
 <button class="vehicle-action lamp-action" :class="{active:s.taillights.value}" :aria-pressed="s.taillights.value" :aria-label="t('Задние фонари','Tail lights')" @click="s.taillights.value=!s.taillights.value"><ActionIcon kind="lamp"/><span>{{t('Задние','Rear lights')}}</span><i/></button>
 </div></div>
 </section></main>
 <div v-if="s.interior.value" class="cockpit-ui"><div class="cockpit-title"><small>{{t('МЕСТО ВОДИТЕЛЯ','DRIVER’S SEAT')}}</small><h3>{{s.car.value.name}}</h3><p>{{t('Перетаскивайте, чтобы осмотреться','Drag to look around')}}</p></div><div class="cockpit-toolbar"><button class="outline" :aria-pressed="s.doors.value" @click="s.doors.value=!s.doors.value"><ActionIcon kind="door"/>{{s.doors.value?t('Закрыть двери','Close doors'):t('Открыть двери','Open doors')}}</button><button v-if="[0,8].includes(s.car.value.shape)" class="outline" :aria-pressed="s.windowsDown.value" @click="s.windowsDown.value=!s.windowsDown.value">▱ {{s.windowsDown.value?t('Поднять окна','Raise windows'):t('Опустить окна','Lower windows')}}</button><button class="outline" @click="cabinFinishes=!cabinFinishes">{{t('ОТДЕЛКА САЛОНА','UPHOLSTERY')}}</button><button class="outline" @click="s.interior.value=false">{{t('ВЫЙТИ','EXIT')}} ↗</button></div><div class="hotspots"><button v-for="d in interiorDetails" :class="{active:s.detail.value===d.id}" @click="inspect(d.id)">+ {{t(d.ru,d.en)}}</button><div v-if="detail" class="hotspot-card"><button @click="s.detail.value=''" :aria-label="t('Закрыть описание','Close detail')">×</button><h3>{{t(detail.ru,detail.en)}}</h3><p>{{t(detail.ruText,detail.enText)}}</p></div></div></div>
 <footer><span class="wordmark">VELOCITY 3</span><NuxtLink to="/garage">{{t('ГАРАЖ / 08','GARAGE / 08')}} ↗</NuxtLink><small><a v-if="s.car.value.shape===0" href="https://sketchfab.com/3d-models/lamborghini-revuelto-099b60042519463ead19ce054d479724" target="_blank" rel="noopener">Lamborghini Revuelto · Anatolian Studios</a><a v-else href="https://sketchfab.com/3d-models/2011-ferrari-458-italia-bb6c7fa565c04ec59cd9d0e0a4d0098c" target="_blank" rel="noopener">Ferrari 458 Italia · Ddiaz Design</a><br>CC BY 4.0 · {{t('Независимый проект','Independent experience')}}</small><a href="#">{{t('НАВЕРХ','BACK TO TOP')}} ↑</a></footer>
</div></template>


<style scoped>
.experience main,.experience footer{transition:opacity .45s ease}
.intro-playing main,.intro-playing footer{visibility:hidden;opacity:0}
.paint-swatches button{background:linear-gradient(135deg,#ffffff70,transparent 32%,#00000045 78%),var(--swatch);box-shadow:inset 0 1px 3px #ffffff55,inset 0 -2px 4px #0005}
.intro-skip{position:fixed;z-index:50;right:30px;bottom:95px;padding:12px 18px;background:#10151bdd;border:1px solid #ffffff40;border-radius:30px;font-size:10px;letter-spacing:1px;backdrop-filter:blur(12px)}
</style>
